import { beforeEach, describe, expect, it, vi } from "vitest";

const agentApi = vi.hoisted(() => ({
  materialEnsure: vi.fn(),
}));

vi.mock("@/lib/tauri", () => ({ agentApi }));

import type { MaterialInfo, StudyContent } from "@/lib/tauri";
import {
  ensureMaterial,
  materialCacheKey,
  materialAbsDir,
  sessionFilePath,
  studyIdentity,
} from "./materials";

/**
 * The material directory is generated by the backend and registered in
 * `index.json`; the front end only caches the resolution. Two properties are
 * load-bearing: the same material must hit the backend once, and a failed
 * resolution must not be cached (the next open retries).
 *
 * The cache is module state that lives for the whole process, so every test
 * uses its own material identity instead of resetting it.
 */

const INFO: MaterialInfo = { kind: "pdfs", dir: "a", relDir: "materials/pdfs/a", title: "A" };

function pdf(name: string): StudyContent {
  return { kind: "pdf", path: `/vault/papers/${name}.pdf`, title: name };
}

function deferred<T>() {
  let resolve!: (value: T) => void;
  let reject!: (error: unknown) => void;
  const promise = new Promise<T>((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

beforeEach(() => {
  agentApi.materialEnsure.mockReset();
});

describe("studyIdentity", () => {
  it("a PDF uses its path, a web page uses its URL (trailing slashes are ignored)", () => {
    expect(studyIdentity({ kind: "pdf", path: "/v/a.pdf", title: "A" })).toBe("pdf:/v/a.pdf");
    expect(studyIdentity({ kind: "url", url: "https://x.com/a/", title: "x" })).toBe(
      "url:https://x.com/a",
    );
    expect(studyIdentity({ kind: "url", url: "https://x.com/a", title: "x" })).toBe(
      "url:https://x.com/a",
    );
    expect(studyIdentity({ kind: "url", url: "https://x.com/a///", title: "x" })).toBe(
      "url:https://x.com/a",
    );
  });
});

describe("the materials directory path", () => {
  it("it lands in <vault>/.bnote/materials/<kind>/<dir>", () => {
    expect(materialAbsDir("/v", "materials/pdfs/ji_qi_xue_xi")).toBe(
      "/v/.bnote/materials/pdfs/ji_qi_xue_xi",
    );
    expect(sessionFilePath("/v", "materials/wxreads/san_ti", "s1-0")).toBe(
      "/v/.bnote/materials/wxreads/san_ti/sessions/s1-0.jsonl",
    );
  });

  it("a trailing slash on the vault path does not produce a double slash", () => {
    expect(materialAbsDir("/v/", "materials/pdfs/a")).toBe("/v/.bnote/materials/pdfs/a");
  });
});

describe("materialCacheKey", () => {
  it("separates vaults and ignores an equivalent URL's trailing slash", () => {
    const content: StudyContent = { kind: "url", url: "https://x.com/p/", title: "P" };
    const a = materialCacheKey("/v1", content);
    const b = materialCacheKey("/v2", content);
    expect(a).not.toBe(b);
    expect(materialCacheKey("/v1", { kind: "url", url: "https://x.com/p", title: "" })).toBe(a);
  });
});

describe("ensureMaterial", () => {
  it("creates the directory through the backend and caches the result", async () => {
    const content = pdf("cache-hit");
    agentApi.materialEnsure.mockResolvedValue(INFO);

    await expect(ensureMaterial("/vault", content)).resolves.toEqual(INFO);
    await expect(ensureMaterial("/vault", content)).resolves.toEqual(INFO);
    expect(agentApi.materialEnsure).toHaveBeenCalledTimes(1);
    expect(agentApi.materialEnsure).toHaveBeenCalledWith(content);
  });

  it("shares one in-flight resolution between concurrent opens", async () => {
    const content = pdf("in-flight");
    const pending = deferred<MaterialInfo>();
    agentApi.materialEnsure.mockReturnValue(pending.promise);

    const first = ensureMaterial("/vault", content);
    const second = ensureMaterial("/vault", content);
    expect(agentApi.materialEnsure).toHaveBeenCalledTimes(1);

    pending.resolve(INFO);
    await expect(Promise.all([first, second])).resolves.toEqual([INFO, INFO]);
  });

  it("resolves null on failure, then retries on the next open instead of caching the failure", async () => {
    const content = pdf("retry-after-failure");
    agentApi.materialEnsure.mockRejectedValueOnce(new Error("no backend"));
    agentApi.materialEnsure.mockResolvedValueOnce(INFO);

    await expect(ensureMaterial("/vault", content)).resolves.toBeNull();
    await expect(ensureMaterial("/vault", content)).resolves.toEqual(INFO);
    expect(agentApi.materialEnsure).toHaveBeenCalledTimes(2);
  });

  it("keeps one directory per vault: the same PDF in another vault asks again", async () => {
    const content = pdf("two-vaults");
    agentApi.materialEnsure.mockResolvedValue(INFO);

    await ensureMaterial("/vault", content);
    await ensureMaterial("/other", content);

    expect(agentApi.materialEnsure).toHaveBeenCalledTimes(2);
  });
});
